// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";
import { drizzle } from "drizzle-orm/d1";
import type { DurableObjectState, ExportedHandler } from "@cloudflare/workers-types";
import * as schema from "./lib/db/schema";
import { runDailyDevotional } from "./lib/devotionals/pipeline";

export class RealtimeRoom {
  private state: DurableObjectState;

  constructor(state: DurableObjectState) {
    this.state = state;
  }

  async fetch(): Promise<Response> {
    return new Response("Realtime room placeholder", { status: 501 });
  }
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      (async () => {
        const db = drizzle(env.DB, { schema });
        const result = await runDailyDevotional({
          db,
          env,
          trigger: "cron",
        });
        if (result.status === "failed") {
          console.error("Daily devotional failed:", result.message);
        } else {
          console.log("Daily devotional:", result.status, result.message);
        }
      })().catch((error) => {
        console.error("Daily devotional schedule error:", error);
      }),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
